 "content": "def transform(grid):
    h,w=len(grid),len(grid[0])
    from collections import Counter
    bg=Counter(x for row in grid for x in row).most_common(1)[0][0]
    rails=[]
    for side,c in [('L',0),('R',w-1)]:
        vals=[(r,grid[r][c]) for r in range(h) if grid[r][c]!=bg]
        if vals:
            color=Counter(v for r,v in vals).most_common(1)[0][0]
            rows=[r for r,v in vals if v==color]
            rails.append((side,c,color,min(rows),max(rows)))
    railcolors={x[2] for x in rails}
    pts=[(r,c,v) for r,row in enumerate(grid) for c,v in enumerate(row) if v!=bg and v not in railcolors]
    dotcolor=pts[0][2]
    out=[row[:] for row in grid]
    # Project each interior marker toward the boundary rail; the first cell is a contrasting cap.
    for r,c,v in pts:
        t=[x for x in rails if (x[0]=='R' and x[1]>c) or (x[0]=='L' and x[1]<c)]
        if not t: continue
        side,edge,rc,lo,hi=t[0]
        end=edge-1 if side=='R' else edge+1
        step=1 if side=='R' else -1
        if c+step != edge and 0<=c+step<w and grid[r][c+step]==bg: out[r][c+step]=4
        x=c+2*step
        while 0<=x<w and x!=edge:
            if grid[r][x]==bg: out[r][x]=v
            x+=step
    # The two ends of each vertical rail mark horizontal beam rows.
    for side,edge,rc,lo,hi in rails:
        for r in {lo,hi}:
            if side=='R':
                for c in range(edge):
                    if grid[r][c]==bg: out[r][c]=dotcolor
            else:
                for c in range(edge+1,w):
                    if grid[r][c]==bg: out[r][c]=dotcolor
    return out
"
}

