 "content": "def transform(grid):
    h,w=len(grid),len(grid[0])
    from collections import Counter
    bg=Counter(v for row in grid for v in row).most_common(1)[0][0]
    # long marker rails are on left/right edges; their color is a beam color
    edge=[]
    for c in (0,w-1):
        vals=[grid[r][c] for r in range(h) if grid[r][c]!=bg]
        if vals: edge.append((c,Counter(vals).most_common(1)[0][0]))
    # For this task, colored markers point along their row/column toward the long edge rails.
    out=[row[:] for row in grid]
    railcolors={v for c,v in edge}
    dots=[(r,c,v) for r,row in enumerate(grid) for c,v in enumerate(row) if v!=bg and v not in railcolors]
    for r,c,v in dots:
        # beams from point along row toward nearer colored rail, turning first cell into 4
        if c < w//2:
            if out[r][c+1]==bg: out[r][c+1]=4
            for x in range(c+2,w):
                if grid[r][x]==bg: out[r][x]=v
        else:
            if out[r][c-1]==bg: out[r][c-1]=4
            for x in range(c-2,-1,-1):
                if grid[r][x]==bg: out[r][x]=v
    return out
"
}

